input.command:
npm init -y >/dev/null && npm i xrpl@5 && npm i -D typescript tsx @types/node && cat > /tmp/probe.mjs <<'EOF'
import { Client } from 'xrpl'
const c = new Client('wss://s.altnet.rippletest.net:51233'); await c.connect()
const si = await c.request({command:'server_info'}); console.log(si.result.info.build_version, si.result.info.validated_ledger)
console.log(JSON.stringify((await c.request({command:'account_info',account:'rJPARZ72zu6Lj7kLKrMczwbRzDkJbdzFvx'})).result.account_data))
console.log(JSON.stringify((await c.request({command:'account_objects',account:'rJPARZ72zu6Lj7kLKrMczwbRzDkJbdzFvx'})).result.account_objects))
const f = await c.request({command:'feature'}); for (const [k,v] of Object.entries(f.result.features)) if (/MPT|Clawback/i.test(v.name)) console.log(v.name, v.enabled)
await c.disconnect()
EOF
cp /tmp/probe.mjs ./probe.mjs && node probe.mjs; rm probe.mjs

