cat > probe.mjs <<'EOF'
import { Client } from 'xrpl'
const c = new Client('wss://s.altnet.rippletest.net:51233'); await c.connect()
const si = await c.request({command:'server_info'}); console.log(si.result.info.build_version, JSON.stringify(si.result.info.validated_ledger))
console.log(JSON.stringify((await c.request({command:'account_info',account:'rJPARZ72zu6Lj7kLKrMczwbRzDkJbdzFvx'})).result.account_data))
console.log(JSON.stringify((await c.request({command:'account_objects',account:'rJPARZ72zu6Lj7kLKrMczwbRzDkJbdzFvx'})).result.account_objects))
try { const f = await c.request({command:'feature'}); for (const [k,v] of Object.entries(f.result.features)) if (/MPT|Clawback/i.test(v.name)) console.log(v.name, v.enabled) } catch(e){console.log('feature err', e.message)}
await c.disconnect()
EOF
node probe.mjs; rm probe.mjs; npm ls xrpl

